"""
Batch adaptive filtering for volatile non-stationary signals.
The returned output is aligned to input indices window_size-1 onward.
"""
import numpy as np

try:
    from scipy.signal import savgol_filter, butter, sosfiltfilt
    from scipy.interpolate import PchipInterpolator
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False

try:
    import pywt
    _HAVE_PYWT = True
except Exception:
    _HAVE_PYWT = False


def _finite_signal(x):
    x = np.asarray(x, dtype=float).reshape(-1).copy()
    if x.size == 0:
        return x
    good = np.isfinite(x)
    if not np.any(good):
        return np.zeros_like(x)
    if not np.all(good):
        ind = np.arange(x.size)
        x[~good] = np.interp(ind[~good], ind[good], x[good])
    return x


def _odd_span(value, n):
    if n < 3:
        return n
    span = max(5, int(round(value)) | 1)
    largest = n if n % 2 else n - 1
    return min(span, largest)


def _reversals(z):
    d = np.diff(z)
    if d.size < 2:
        return 0
    eps = 1e-10 * (np.std(z) + 1.0)
    s = np.sign(d)
    if s[0] == 0:
        s[0] = 1
    for i in range(1, s.size):
        if abs(d[i]) <= eps:
            s[i] = s[i - 1]
    return int(np.sum(s[1:] * s[:-1] < 0))


def _fallback_smooth(x, span):
    pad = span // 2
    return np.convolve(np.pad(x, pad, mode="edge"),
                       np.ones(span) / span, mode="valid")


def _wavelet_candidates(x):
    if not _HAVE_PYWT or x.size < 16:
        return []
    out = []
    for name in ("db4", "sym4"):
        try:
            wave = pywt.Wavelet(name)
            level = min(5, pywt.dwt_max_level(x.size, wave.dec_len))
            if level < 1:
                continue
            coeffs = pywt.wavedec(x, wave, mode="symmetric", level=level)
            detail = coeffs[-1]
            sigma = 1.4826 * np.median(np.abs(detail - np.median(detail))) + 1e-10
            base = sigma * np.sqrt(2.0 * np.log(max(2, x.size)))
            for mode in ("soft", "hard"):
                c = [coeffs[0]]
                for j, detail_j in enumerate(coeffs[1:], 1):
                    threshold = base * (2.0 ** (-0.12 * j))
                    c.append(pywt.threshold(detail_j, threshold, mode=mode))
                y = pywt.waverec(c, wave, mode="symmetric")[:x.size]
                if y.size == x.size and np.all(np.isfinite(y)):
                    out.append(y)
        except Exception:
            pass
    return out


def adaptive_filter(x, window_size=20):
    x = _finite_signal(x)
    if len(x) < window_size:
        raise ValueError("Input signal length must be >= window_size")
    return np.convolve(x, np.ones(window_size) / window_size, mode="valid")


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = _finite_signal(x)
    n = x.size
    if n < window_size:
        raise ValueError("Input signal length must be >= window_size")
    if n < 5:
        return x[window_size - 1:].copy()

    candidates = [x.copy()]
    spans = []
    for multiple in (1.0, 1.5, 2.0, 3.0):
        span = _odd_span(multiple * window_size, n)
        if span >= 5 and span not in spans:
            spans.append(span)

    if _HAVE_SCIPY:
        for span in spans:
            candidates.append(savgol_filter(x, span, 3 if span >= 7 else 2,
                                             mode="interp"))
        if n > 15:
            for cutoff in (0.06, 0.10, 0.16):
                try:
                    sos = butter(3, cutoff, btype="lowpass", output="sos")
                    candidates.append(sosfiltfilt(sos, x))
                except Exception:
                    pass
    else:
        candidates.extend(_fallback_smooth(x, s) for s in spans)

    candidates.extend(_wavelet_candidates(x))

    xstd = np.std(x)
    best, best_score = x.copy(), np.inf
    for y in candidates:
        y = np.nan_to_num(np.asarray(y, dtype=float), nan=0.0,
                          posinf=0.0, neginf=0.0)
        if y.size != n:
            continue
        ystd = np.std(y)
        if xstd > 1e-12 and ystd > 1e-12:
            corr = np.corrcoef(x, y)[0, 1]
        else:
            corr = 1.0 if xstd <= 1e-12 else 0.0
        if not np.isfinite(corr) or corr < 0.35:
            continue
        if xstd > 1e-10 and ystd < 0.12 * xstd:
            continue
        mae = np.mean(np.abs(y - x))
        score = 0.40 * min(mae, 2.0) + 0.60 * min(_reversals(y) / 50.0, 2.0)
        if score < best_score:
            best, best_score = y, score

    raw = best[window_size - 1:].copy()
    nr = raw.size
    if not _HAVE_SCIPY or nr < 5:
        return raw

    small_span = _odd_span(min(window_size, nr), nr)
    residual = raw - savgol_filter(raw, small_span,
                                   2 if small_span < 7 else 3, mode="interp")
    prominence = 1.5 * (
        1.4826 * np.median(np.abs(residual - np.median(residual))) + 1e-8
    )
    radius = max(1, window_size // 3)
    scales = list(dict.fromkeys([
        _odd_span(max(5, window_size // 2), nr),
        _odd_span(max(5, window_size), nr),
        _odd_span(max(5, 2 * window_size), nr),
    ]))

    evidence = []
    for span in scales:
        smooth = savgol_filter(raw, span, 2 if span < 7 else 3, mode="interp")
        d = np.diff(smooth)
        s = np.sign(d)
        if s.size:
            s[s == 0] = 1
        evidence.append(np.flatnonzero(s[:-1] != s[1:]) + 1)

    middle = evidence[len(evidence) // 2]
    knots = [0]
    for p in middle:
        support = sum(np.any(np.abs(q - p) <= radius) for q in evidence)
        lo, hi = max(0, p - radius), min(nr - 1, p + radius)
        level = abs(raw[p] - 0.5 * (
            np.median(raw[lo:p + 1]) + np.median(raw[p:hi + 1])
        ))
        if support >= 2 and level >= prominence and p > knots[-1] + 1:
            knots.append(int(p))
    if knots[-1] != nr - 1:
        knots.append(nr - 1)

    if len(knots) < 3:
        return raw
    values = np.array([
        np.median(raw[max(0, p - radius):min(nr, p + radius + 1)])
        for p in knots
    ])
    values[0], values[-1] = raw[0], raw[-1]
    try:
        return np.asarray(PchipInterpolator(knots, values)(np.arange(nr)), dtype=float)
    except Exception:
        return raw


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (2 * np.sin(2 * np.pi * 0.5 * t)
             + 1.5 * np.sin(2 * np.pi * 2 * t)
             + 0.5 * np.sin(2 * np.pi * 5 * t)
             + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t))
    clean += 0.1 * t * np.sin(0.2 * t)
    clean += np.cumsum(rng.randn(length) * 0.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = _finite_signal(noisy_signal)
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {"filtered_signal": filtered, "clean_signal": None,
                "noisy_signal": None, "correlation": 0, "noise_reduction": 0,
                "signal_length": len(filtered)}

    delay = window_size - 1
    clean = clean_signal[delay:]
    noisy = noisy_signal[delay:]
    m = min(filtered.size, clean.size)
    filtered, clean, noisy = filtered[:m], clean[:m], noisy[:m]
    corr = (np.corrcoef(filtered, clean)[0, 1]
            if m > 1 and np.std(filtered) > 0 and np.std(clean) > 0 else 0)
    before, after = np.var(noisy - clean), np.var(filtered - clean)
    return {
        "filtered_signal": filtered,
        "clean_signal": clean,
        "noisy_signal": noisy,
        "correlation": corr,
        "noise_reduction": (before - after) / before if before > 0 else 0,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")

